@Test func removingLastNutrientClearsStoredBasisOnModelUpdate() throws {
    var draft = ProductDraft(
        name: "しょうゆ", type: "調味料", calories: "0",
        nutrientBasisAmount: "100", nutrientBasisUnit: " g　"
    )
    let product = Product(values: try draft.validated().get())
    #expect(product.calories == 0)
    #expect(product.nutrientBasisAmount == 10000)
    #expect(product.nutrientBasisUnit == "g")

    draft.calories = ""
    let editedAt = Date(timeIntervalSince1970: 1_700_000_000)
    product.update(values: try draft.validated().get(), image: nil, updatedAt: editedAt)

    #expect(product.updatedAt == editedAt)
    expectUnsetValues(product)
}

@Test func nutrientAmountsRequireAtLeastOneValueAndCountEveryExplicitZero() throws {
    #expect(ProductNutrition.Amounts.create() == nil)
    let calories = try EnergyKcal.parse("0").get()
    let grams = try NutrientGrams.parse("0").get()
    let amounts = [
        ProductNutrition.Amounts.create(calories: calories),
        ProductNutrition.Amounts.create(protein: grams),
        ProductNutrition.Amounts.create(fat: grams),
        ProductNutrition.Amounts.create(sugar: grams),
        ProductNutrition.Amounts.create(carbohydrates: grams),
    ]

    #expect(amounts.allSatisfy { $0 != nil })
}

@Test func domainValuesComposeWithoutAFormAndKeepIndependentNutrients() throws {
    let calories = try EnergyKcal.parse("12.34").get()
    let protein = try NutrientGrams.parse("0.01").get()
    let fat = try NutrientGrams.parse("1.20").get()
    let carbohydrates = try NutrientGrams.parse("4.56").get()
    let amounts = try #require(
        ProductNutrition.Amounts.create(
            calories: calories, protein: protein, fat: fat, carbohydrates: carbohydrates)
    )
    let nutrition = ProductNutrition(
        amounts: amounts, basisAmount: try NutrientBasisAmount.parse("15").get(),
        basisUnit: try NutrientBasisUnit.parse("mL").get()
    )
    let product = ProductValues(
        name: try ProductName.parse("だし").get(), type: try ProductType.parse("和風 だし").get(),
        priceYen: try PriceYen.parse("398").get(), nutrition: nutrition
    )

    #expect(product.name.value == "だし")
    #expect(product.type.value == "和風 だし")
    #expect(product.priceYen?.value == 398)
    #expect(product.nutrition?.amounts.calories?.hundredths == 1234)
    #expect(product.nutrition?.amounts.protein?.hundredths == 1)
    #expect(product.nutrition?.amounts.fat?.hundredths == 120)
    #expect(product.nutrition?.amounts.sugar == nil)
    #expect(product.nutrition?.amounts.carbohydrates?.hundredths == 456)
    #expect(product.nutrition?.basisAmount.hundredths == 1500)
    #expect(product.nutrition?.basisUnit.value == "mL")
}

/// 前後の空白を除いた、空でない商品名。
struct ProductName: Equatable {
    let value: String

    private init(_ value: String) {
        self.value = value
    }

    static func parse(_ input: String) -> Result<Self, ProductValueError> {
        ProductValueParser.requiredText(input).map(Self.init)
    }
}

/// 前後の空白を除いた、空でない種類。内部の表記は保持する。
struct ProductType: Equatable {
    let value: String

    private init(_ value: String) {
        self.value = value
    }

    static func parse(_ input: String) -> Result<Self, ProductValueError> {
        ProductValueParser.requiredText(input).map(Self.init)
    }
}

/// 0より大きく、小数点以下2桁までの基準量。単位は基準単位と組み合わせる。
struct NutrientBasisAmount: Equatable {
    let hundredths: Int64

    private init(_ hundredths: Int64) {
        self.hundredths = hundredths
    }

    static func parse(_ input: String) -> Result<Self, ProductValueError> {
        ProductValueParser.number(input, decimalPlaces: 2).flatMap { amount in
            guard amount > 0 else {
                return .failure(.mustBePositive)
            }

            return .success(Self(amount))
        }
    }
}

private func value<Value>(
    _ input: String, field: Field, using parse: (String) -> Result<Value, ProductValueError>
) -> Result<Value, ValidationError> {
    parse(input).mapError { error in
        let reason: FailureReason

        switch error {
        case .required:
            reason = .required
        case .invalidFormat:
            reason = .invalidFormat
        case .outOfRange:
            reason = .outOfRange
        case .mustBePositive:
            reason = .mustBePositive
        }

        return ValidationError(field: field, reason: reason)
    }
}

/// 不変条件を満たした値を組み合わせた商品情報。フォームを経由せずに構成できる。
struct ProductValues: Equatable {
    let name: ProductName
    let type: ProductType
    let priceYen: PriceYen?
    let nutrition: ProductNutrition?
}

/// 入力済みの栄養値と、全栄養値に共通する基準。
struct ProductNutrition: Equatable {
    let amounts: Amounts
    let basisAmount: NutrientBasisAmount
    let basisUnit: NutrientBasisUnit

    /// 一つ以上の栄養値を持つ。各項目の未設定と0を区別する。
    struct Amounts: Equatable {
        let calories: EnergyKcal?
        let protein: NutrientGrams?
        let fat: NutrientGrams?
        let sugar: NutrientGrams?
        let carbohydrates: NutrientGrams?

        private init(
            calories: EnergyKcal?, protein: NutrientGrams?, fat: NutrientGrams?,
            sugar: NutrientGrams?, carbohydrates: NutrientGrams?
        ) {
            self.calories = calories
            self.protein = protein
            self.fat = fat
            self.sugar = sugar
            self.carbohydrates = carbohydrates
        }

        static func create(
            calories: EnergyKcal? = nil, protein: NutrientGrams? = nil, fat: NutrientGrams? = nil,
            sugar: NutrientGrams? = nil, carbohydrates: NutrientGrams? = nil
        ) -> Self? {
            guard calories != nil || [protein, fat, sugar, carbohydrates].contains(where: { $0 != nil }) else {
                return nil
            }

            return Self(calories: calories, protein: protein, fat: fat, sugar: sugar, carbohydrates: carbohydrates)
        }
    }
}

let amounts = ProductNutrition.Amounts.create(
    calories: validatedCalories, protein: validatedProtein, fat: validatedFat,
    sugar: validatedSugar, carbohydrates: validatedCarbohydrates
)
guard let amounts else {
    return .success(
        ProductValues(
            name: validatedName, type: validatedType, priceYen: validatedPriceYen, nutrition: nil
        )
    )
}

let basisAmount: NutrientBasisAmount
switch value(nutrientBasisAmount, field: .nutrientBasisAmount, using: NutrientBasisAmount.parse) {
case .success(let parsed):
    basisAmount = parsed
case .failure(let error):
    return .failure(error)
}

return value(nutrientBasisUnit, field: .nutrientBasisUnit, using: NutrientBasisUnit.parse).map { unit in
    ProductValues(
        name: validatedName, type: validatedType, priceYen: validatedPriceYen,
        nutrition: ProductNutrition(amounts: amounts, basisAmount: basisAmount, basisUnit: unit)
    )
}

// 表示・保存テスト用。旧データに含まれる未正規化の文字列や欠損もそのまま再現する。
@MainActor
extension Product {
    convenience init(id: UUID = UUID(), name: String, type: String, updatedAt: Date = Date()) throws {
        let draft = ProductDraft(name: "テスト商品", type: "調味料")
        self.init(id: id, values: try draft.validated().get(), updatedAt: updatedAt)
        setValue(forKey: \.name, to: name)
        setValue(forKey: \.type, to: type)
    }
